// n8n sends { execution, workflow } for failed executions and
// { trigger, workflow } when a trigger node itself failed (e.g. auth error on poll).
const { execution, trigger, workflow = {} } = $json;
const err = execution?.error ?? trigger?.error ?? {};

const summary = {
  workflow_id: workflow.id ?? null,
  workflow_name: workflow.name ?? 'unknown workflow',
  node_name: execution?.lastNodeExecuted ?? err.node?.name ?? null,
  error_message: String(err.message ?? 'Unknown error').slice(0, 2000),
  error_details: {
    name: err.name ?? null,
    description: err.description ?? null,
    httpCode: err.httpCode ?? err.context?.httpCode ?? null,
    stack: (err.stack ?? '').split('\n').slice(0, 8).join('\n'),
  },
  execution_id: execution?.id ?? null,
  execution_url: execution?.url ?? null,
  execution_mode: execution?.mode ?? trigger?.mode ?? null,
  retry_of: execution?.retryOf ?? null,
};

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
summary.alert_subject = '[n8n error] ' + summary.workflow_name + ' – ' + (summary.node_name ?? 'trigger');
summary.alert_html = [
  '<h3>Workflow failed / Workflow fehlgeschlagen</h3>',
  '<table cellpadding="4">',
  '<tr><td><b>Workflow</b></td><td>' + esc(summary.workflow_name) + '</td></tr>',
  '<tr><td><b>Node</b></td><td>' + esc(summary.node_name ?? '–') + '</td></tr>',
  '<tr><td><b>Error</b></td><td>' + esc(summary.error_message) + '</td></tr>',
  '<tr><td><b>Mode</b></td><td>' + esc(summary.execution_mode ?? '–') + '</td></tr>',
  '</table>',
  summary.execution_url ? '<p><a href="' + esc(summary.execution_url) + '">Open execution ' + esc(summary.execution_id) + '</a></p>' : '',
].join('\n');

return [{ json: summary }];
